    public static function raw(string $name): string
    {
        return self::ICONS[$name]['body'] ?? '';
    }

    public static function svg(string $name, string $class = 'w-6 h-6'): string
    {
        $icon = self::ICONS[$name] ?? null;

        if ($icon === null) {
            return '';
        }

        $fill = $icon['stroke'] ? 'none' : 'currentColor';

        return sprintf(
            '<svg class="%s" viewBox="%s" fill="%s" aria-hidden="true">%s</svg>',
            htmlspecialchars($class, ENT_QUOTES),
            $icon['viewBox'],
            $fill,
            $icon['body']
        );
    }
}
